// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Binary".

The motif draws upon the Western concept of binary logic,
yet at its core, it mirrors the traditional Japanese principles
of Nōtan and In-Yō duality which is an art form in which light
and shadow do not oppose each other, but rather co-exist in
absolute, mutual dependence.

A continuation of my watercolour experiments. Just a still life.

Interaction:
- Mouse: Pan
- Mouse Wheel: Zoom

*/

const scale = Math.max(1, devicePixelRatio)
let theShader, moves=[0,0], wheelDelta = 0, wheelOffset = 0;

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2999191/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function mouseMove() {
	if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) return
	moves[0] += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) * scale
	moves[1] += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) * scale
}

function mouseWheel(e) {
	if (wheelDelta * e.deltaY < 0) {
		wheelDelta = e.deltaY
	} else {
		wheelDelta = lerp(wheelDelta, e.deltaY, 0.05)
	}
	wheelOffset += wheelDelta
}

function draw() {
  mouseMove()
  shader(theShader)
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("move", moves)
  theShader.setUniform("wheel", [wheelDelta, wheelOffset])
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform vec2 resolution;
uniform vec2 move;
uniform vec2 wheel;
#define FC gl_FragCoord.xy
#define R resolution
#define S smoothstep
#define SE(v,a) S(a+1./MN,a-1./MN,v)
#define MN min(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
float rnd(vec2 a) {
	vec3 p=fract(a.xyx*.1031);
	p+=dot(p,p.yzx+33.33);
	return fract((p.x+p.y)*p.z);
}
float noise(vec2 p) {
	vec2 i=floor(p), u=S(i,i+1.,p), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+k.xx);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
float fbm(vec2 p) {
	float t=.0, a=1., h=.0; mat2 m=mat2(1.6,-.2,.8,1);
	for (int i=0; i<5; i++) {
		t+=a*noise(p);
		p*=2.;
		a/=2.;
		h+=a;
	}
	return t/h;
}
vec3 tree(vec2 uv, float k, out float d, float w) {
	vec3 col=vec3(0);
	vec2 p=uv, q=uv;
	float f=length((uv+vec2(-.05,.48))*mat2(cos(1.-vec4(0,11,33,0)))*vec2(.3,1));
	f=SE(f,.02+.01*fbm(uv-fbm(uv.yx*12.))-.0002*k);
	col=mix(col,mix(vec3(.08),vec3(.06),k),f);
	uv.x-=.02*sin(22.*uv.y-fbm(uv*12.)+4.2);
	uv.y-=clamp(uv.y,-.4,.0);
	float e=length(uv);
	e=SE(e,.01-.0002*k);
	col=mix(col,mix(vec3(.1),vec3(.06),k),e);
	p.x+=.05*fbm(p.yy*33.33+.8*fbm(p.yy*222.22-12.*fbm(uv))+1.6)-.05;
	p.y-=clamp(p.y,-.2,.1);
	d=length(p);
	d=SE(d,.05-.25*clamp(q.y,-.4,.13)-.0004*k);
	float x=fbm(sin(23.*q.x)+q.yy*33.33-2.*fbm(q.yy*222.22));
	col=mix(col,mix(mix(vec3(.15),vec3(.125),k),vec3(.125),1.6*x),d);
	d=max(max(d,e),min(f,max(-f,w)));
	return col;
}
vec3 sun(vec2 uv, float k, out float d) {
	vec3 col=vec3(1);
	d=length(uv);
	d=SE(d,.2+.0003*k);
	uv*=rot(.8*atan(uv.x,uv.y*.85));
	uv.y+=.5;
	float x=fbm(sin(23.*uv.x)+uv.yy*33.33-2.*fbm(uv.yy*222.22));
	col=mix(col,mix(mix(vec3(.8,.2,.2),vec3(.7,.15,.05),k),vec3(.7,.15,.05),.5*x),d);
	return col;
}
vec3 signature(vec2 uv, float k, out float d) {
	vec3 col=vec3(0);
	vec2 p=uv*13.+vec2(-2.5,2.6);
	p.y+=.2*sin(p.x*33.-12.3*p.y-1.2*sin(p.x*10.-2.)-cos(p.x*10.+1.));
	p.y+=.2*(sin(p.y)-sin(p.x*2.));
	p.x-=clamp(p.x,-.2,.2);
	d=length(p);
	d=SE(d,.18-.015*k);
	col=mix(col,mix(vec3(.095)*.1,vec3(.09),k),d);
	return col;
}
vec3 paper(vec2 uv, float k, out float d) {
	vec3 col=vec3(1);
	uv=vec2(abs(uv.x)-.3-.0025*fbm(uv.yy*2.-22.*fbm(uv.yx*13.37-.42)),abs(uv.y)-.4-.0025*fbm(uv.xx-2.*fbm(uv.yx*22.22)));
	d=max(uv.x,uv.y);
	d=SE(d,.07-.01*fbm(uv));
	float x=mix(.0,.1,fbm(sin(23.*uv.x)+uv.yy*33.33-2.*fbm(uv.yy*222.22)));
	col=mix(col,mix(mix(vec3(.98,.94,.9),vec3(.97,.92,.9),k),vec3(.97,.92,.9),x),d);
	return col;
}
vec3 render(vec2 uv) {
	vec3 col=vec3(1);
	float a, b, c, d, h=200., k=sin(uv.x*h+uv.y*h*2.)-sin(uv.x*h-uv.y*h*2.);
	col=mix(col,paper(uv,k,a),a);
	col=mix(col,sun(uv,k,b),b);
	col=mix(col,tree(uv,k,c,a),c);
	col=mix(col,signature(uv,k,d),d);
	col=mix(mix(vec3(.95,.92,.9)*.1,vec3(.9,.87,.85)*.1,k),col,max(max(a,max(b,c)),d));
	return col;
}
void main() {
	vec2 uv=(FC-.5*R)/MN;
	float zoom=.5*sin(wheel.y/1e3);
	uv.y-=move.y/MN;
	uv.x-=move.x/MN;
	uv*=1.+zoom;	
	vec3 col=render(uv);
	vec2 c=FC/R;
	c*=1.-c.yx;
	float v=c.x*c.y*25.;
	col=mix(tanh(col*col*col)*.2,col,clamp(pow(v,.125),.0,1.));
	O=vec4(col,1);
}

